function casePhones(c){const phones=new Map();for(const p of c.phones){if(!p.n)continue;const existing=phones.get(p.n);if(existing)existing.src=[...new Set([...existing.src,...p.src])];else phones.set(p.n,{n:p.n,src:[...p.src]})}return [...phones.values()]}
